<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Platform/manage')}">平台分类列表</a>|					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/add')}','添加分类',800,560,true,false,false,addbtn,'add',true);">添加分类</a>					<a href="{pigcms{:U('Platform/activity_list')}">平台活动列表</a>|					<a href="" class="on">分类管理员审核列表</a>					<a href="{pigcms{:U('Platform/examine_refundList')}">退款审核列表</a>|					<a href="{pigcms{:U('Platform/platform_config')}">配置项</a>|				</ul>			</div>			<table class="search_table" width="100%">				<!-- <tr>					<td>						<form action="/admin.php?g=System&c=Classify&a=checkList" method="get">							<input type="hidden" value="Classify" name="c"></input>							<input type="hidden" value="checkList" name="a"></input>							select name="city_id" style="width:200px;">								<option value="0">全部城市</option>								<if condition="!empty($city_list)">									<volist name="city_list" id="vo">										<option value="{pigcms{$vo['area_id']}"  <if condition="$vo['area_id'] eq $city_id">selected="selected"</if>>{pigcms{$vo['area_name']}</option>									</volist>								<else/>									<option value="">无</option>								</if>							</select							<if condition="$now_area['area_type'] lt 2 OR $system_session['level'] eq 2 ">								选择城市：								<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}"  style="display:inline"></div>								<input type="submit" value="查询" class="button"/>							</if>						</form>					</td>				</tr> -->				<tr>					<td>						<div class="mainnav_title">							<ul>								<a href="{pigcms{:U('Platform/checkList')}"  class="on">待审核分类管理员列表</a>|								<a href="{pigcms{:U('Platform/hasCheckList')}">已审核分类管理员列表</a>							</ul>						</div>					</td>				</tr>				</table>			<!--<table class="search_table" width="100%">				<tr>					<td>					</td>				</tr>			</table>-->			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>						</colgroup>						<thead>							<tr>								<th>姓名</th>								<th>手机号</th>								<th>微信号</th>								<th>身份证号</th>								<th>区域</th>								<th>分类</th>								<th>图片</th>								<th>添加时间</th>								<th>状态</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="!empty($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.name}</td>										<td>{pigcms{$vo.phone}</td>										<td>{pigcms{$vo.wx_card}</td>										<td>{pigcms{$vo.id_card}</td>										<td>{pigcms{$vo.province_name}-{pigcms{$vo.city_name}</td>										<td>{pigcms{$vo.cate_name}</td>										<td><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/imgdetail',array('id'=>$vo['id']))}','查看图片信息',680,560,true,false,false,'','edit',true);">查看</a></td>										<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>										<td>											<if condition="$vo.status eq 0">												<font style="color: red;">未审核</font>											</if>											</td>										<td class="textcenter"><a href="javascript:void(0);" onclick="toCheck({pigcms{$vo.id});">审核</a>&nbsp; | &nbsp;<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/detail',array('id'=>$vo['id']))}','查看信息详情',680,560,true,false,false,verifybtn,'edit',true);">查看详细</a>&nbsp; | &nbsp;<a href="javascript:void(0);" onclick="toDelItem({pigcms{$vo.id});">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="9">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><script type="text/javascript">layer.config({        extend: 'extend/layer.ext.js'});function toCheck(id){    layer.confirm('是否审核通过?', {                       btn: ['通过', '驳回']        ,offset: '400px'       , btn1:function(){            $.post("{pigcms{:U('Platform/verifyManage')}",{id:id},function(data){			  data=parseInt(data);			  if(!data){		          layer.msg('审核通过!', {offset: '400px',icon: 1,time: 2000},function(){location.reload()});			   }		    },'JSON');        }        , btn2: function () {           	layer.prompt({			  formType: 2,			  title: '驳回原因:',			  offset: '400px',			  maxlength:255			}, function(value, index, elem){				$.post("{pigcms{:U('Platform/leaveMessage')}",{'id':id,'message':value},function(data){				  data=parseInt(data);				  if(!data){			            layer.msg('审核未通过!', {offset: '400px',icon: 1,time: 2000},function(){location.reload()});				   }else{				   		layer.msg('操作失败,请重试!!', {offset: '400px',icon: 2,time: 2000},function(){location.reload()});				   }			    },'JSON');			  layer.close(index);			});        }    });}/***删除***/function toDelItem(id){    if(confirm('您确定删除此项吗？')){    $.post("{pigcms{:U('Platform/delItem')}",{id:id},function(data){	  data=parseInt(data);	  if(!data){          window.location.reload();	   }     },'JSON');   }else{     return false;   }}</script><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js?{pigcms{:time()}"></script><include file="Public:footer"/>